#include <iostream>
#include <string>
#include <cctype>

int main() {
    std::string line;
    std::getline(std::cin, line);

    std::string cleaned;
    for (char ch : line) {
        if (ch == ' ') {
            continue;
        }
        cleaned += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    }

    int left = 0;
    int right = static_cast<int>(cleaned.size()) - 1;
    bool palindrome = true;
    while (left < right) {
        if (cleaned[left] != cleaned[right]) {
            palindrome = false;
            break;
        }
        ++left;
        --right;
    }

    std::cout << (palindrome ? "Yes" : "No") << std::endl;
    return 0;
}
