#include <iostream>

class Shape {
public:
    virtual int area() const = 0;
    virtual ~Shape() {
    }
};

class Rectangle : public Shape {
private:
    int width;
    int height;

public:
    Rectangle(int w, int h) : width(w), height(h) {
    }

    int area() const override {
        return width * height;
    }
};

class Square : public Shape {
private:
    int side;

public:
    explicit Square(int s) : side(s) {
    }

    int area() const override {
        return side * side;
    }
};

int main() {
