class MyString {
private:
    char* data;

public:
    explicit MyString(const char* s) {
        int n = static_cast<int>(std::strlen(s));
        data = new char[n + 1];
        for (int i = 0; i <= n; ++i) {
            data[i] = s[i];
        }
    }

    MyString(const MyString& other) {
        int n = static_cast<int>(std::strlen(other.data));
        data = new char[n + 1];
        for (int i = 0; i <= n; ++i) {
            data[i] = other.data[i];
        }
    }

    MyString& operator=(const MyString& other) {
        if (this != &other) {
            int n = static_cast<int>(std::strlen(other.data));
            char* newData = new char[n + 1];
            for (int i = 0; i <= n; ++i) {
                newData[i] = other.data[i];
            }
            delete[] data;
            data = newData;
        }
        return *this;
    }

    ~MyString() {
        delete[] data;
    }

    void setChar(int index, char c) {
        data[index] = c;
    }

    const char* c_str() const {
        return data;
    }
};

int main() {
    std::string s1, s2;
    std::cin >> s1 >> s2;

    MyString x(s1.c_str());
    MyString y(s2.c_str());

    y = x;
    x.setChar(0, 'X');

    std::cout << x.c_str() << " " << y.c_str() << std::endl;
