#include <iomanip>
#include <iostream>
#include <vector>

template <typename T>
T total(const std::vector<T>& v) {
    T sum{};
    for (const T& x : v) {
        sum += x;
    }
    return sum;
}

template <typename T>
T maximum(const std::vector<T>& v) {
    T best = v.front();
    for (const T& x : v) {
        if (x > best) {
            best = x;
        }
    }
    return best;
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<double> v(n);
    for (double& x : v) {
        std::cin >> x;
    }

    std::cout << std::fixed << std::setprecision(2);
    std::cout << total(v) << '\n';
    std::cout << maximum(v) << '\n';
    return 0;
}
