#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<std::string> words(n);
    for (std::string& w : words) {
        std::cin >> w;
    }

    std::sort(words.begin(), words.end(),
              [](const std::string& a, const std::string& b) {
                  if (a.size() != b.size()) {
                      return a.size() < b.size();
                  }
                  return a < b;
              });

    for (const std::string& w : words) {
        std::cout << w << '\n';
    }
    return 0;
}
